-- 17A POSTCHECKS P3c state PRE: one read-only statement; ok must be true on every row
-- 17A STORAGE PRIVACY: PROPOSAL ONLY. NOT APPLIED ANYWHERE. GENERATED by db/proposed/17a-storage-privacy/build.mjs (node build.mjs --check fails if this file drifts from its inputs).
-- Apply gate: NO prod SQL and NO Storage API operation without Joe's relayed yes + Sentinel's pass + Atlas's review of the migrations + a backup. Sentinel's inventory/backup files were NOT available to this draft (see README). Order: README.md.
-- Run as postgres, ONE transaction, ON_ERROR_STOP (psql -v ON_ERROR_STOP=1) or a single-call SQL executor; right after BEGIN come SET LOCAL lock_timeout = '5s', the repo-wide pack advisory lock, and SET LOCAL lock_timeout = '5s' again.
-- Read-only (a single SELECT over the catalog; the scan in P3c reads counts only).
WITH a(name, actual) AS (
  SELECT 'req.P1_applied_chat_images' AS name, coalesce((SELECT coalesce(string_agg(p.policyname::text, ',' ORDER BY p.policyname::text COLLATE "C"),'(none)') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.cmd IN ('SELECT','ALL') AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'chat-images'), 'ABSENT') AS actual
  UNION ALL SELECT 'req.public_assets_bucket_public' AS name, coalesce((SELECT b.public::text FROM storage.buckets b WHERE b.id = 'public-assets'), 'ABSENT') AS actual
  UNION ALL SELECT 'req.public_assets_object_count_ge_min' AS name, coalesce(((SELECT count(*) FROM storage.objects o WHERE o.bucket_id = 'public-assets') >= 6)::text, 'ABSENT') AS actual
  UNION ALL SELECT 'req.no_public_table_references_chat_images' AS name, coalesce((WITH cols AS (
  SELECT c.table_name::text AS t, c.column_name::text AS col FROM information_schema.columns c JOIN information_schema.tables tb ON tb.table_schema = c.table_schema AND tb.table_name = c.table_name
  WHERE c.table_schema = 'public' AND tb.table_type = 'BASE TABLE' AND c.data_type IN ('text','character varying','json','jsonb') AND c.table_name NOT LIKE '\_bak\_%'
), hits AS (
  SELECT t, col, (xpath('/row/n/text()', query_to_xml(format('select count(*) as n from public.%I where strpos(%I::text, %L) > 0', t, col, 'chat-images'), false, true, '')))[1]::text::int AS n FROM cols
) SELECT coalesce(string_agg(t || '.' || col || '=' || n, ',' ORDER BY t, col), 'none') FROM hits WHERE n > 0), 'ABSENT') AS actual
  UNION ALL SELECT 'bucket.chat-images.public' AS name, coalesce((SELECT b.public::text FROM storage.buckets b WHERE b.id = 'chat-images'), 'ABSENT') AS actual
), e(name, expected, accepted) AS (VALUES
  ('req.P1_applied_chat_images', 'chat_images_owner_admin_read', ARRAY['chat_images_owner_admin_read']::text[]),
  ('req.public_assets_bucket_public', 'true', ARRAY['true']::text[]),
  ('req.public_assets_object_count_ge_min', 'true', ARRAY['true']::text[]),
  ('req.no_public_table_references_chat_images', 'none', ARRAY['none']::text[]),
  ('bucket.chat-images.public', 'true', ARRAY['true']::text[])
), r AS (SELECT e.name, coalesce(e.expected, 'RECORD ONLY') AS expected, a.actual, (e.accepted IS NULL OR a.actual = ANY (e.accepted)) AS ok FROM e LEFT JOIN a USING (name))
SELECT '000_ALL_OK' AS name, 'PRE' AS expected, 'PRE' AS actual, bool_and(ok) AS ok FROM r
UNION ALL SELECT name, expected, actual, ok FROM r
ORDER BY 1;
